addPlant(kind,row,col){this.targetIndex=null;const s=this.state,d=C.PLANTS[kind];const p={id:this.id(),kind,row,col,x:col+.5,y:row+.5,hp:d.hp,maxHp:d.hp,layer:d.layer||'plant',age:0,armed:false,attackTimer:0,timer:0,production:kind==='sunflower'?5+this.random()*3:5,mode:'idle',sleeping:!!(d.mushroom&&!['night','fog'].includes(s.levelDef.environment)&&s.levelDef.mode!=='boss')};if(kind==='cob-cannon'){p.reload=0;p.mode='ready';}if(kind==='spikerock')p.crushHits=9;p.supportHeight=this.supportHeight(p);if(this.gameMode==='skill')this.initSkill(p);s.plants.push(p);if(p.layer==='base')for(const other of s.plants)if(other.row===row&&other.col===col)other.supportHeight=this.supportHeight(other);this.emit('plant',p);return p;}
// Reconstructed boss supply safety: each six-card bag contains every original
