updateBoss(dt){const s=this.state,b=s.boss;if(b.hp<=0)return;if(b.pending){b.pending.timer-=dt;if(b.pending.timer<=0){const h=b.pending;for(const p of s.plants)if(p.row>=h.row&&p.row<h.row+h.rows&&p.col>=h.col&&p.col<h.col+h.cols){p.hp=0;this.emit('smash',p);}this.emit('boss-impact',{kind:h.kind,x:h.col+.5,y:h.row+.5,row:h.row});b.pending=null;}}if(b.frozen>0){b.frozen-=dt;return;}b.timer-=dt;b.attackTimer=Math.max(0,b.attackTimer-dt);if(b.exposed&&b.ballTimer>0){b.ballTimer-=dt;if(b.ballTimer<=0){const kind=this.random()<.5?'fire-ball':'ice-ball';s.projectiles.push({id:this.id(),kind,row:b.row,x:9,y:b.y,vx:-.8,damage:9999});b.attackTimer=1;}}if(b.timer<=0){b.exposed=!b.exposed;b.timer=b.exposed?18:22;b.ballTimer=b.exposed?5:0;b.row=Math.floor(this.random()*s.rows);b.y=b.row+.5;this.emit('boss',{...b,kind:'zomboss'});if(!b.exposed){b.cycle=(b.cycle||0)+1;const attack=b.cycle%4;if(attack===2){b.pending={kind:'stomp',row:Math.min(3,b.row),col:5,rows:2,cols:4,timer:3};this.emit('boss-warning',b.pending);}else if(attack===0){b.pending={kind:'rv',row:Math.floor(this.random()*4),col:Math.floor(this.random()*4),rows:2,cols:3,timer:3};this.emit('boss-warning',b.pending);for(let i=0;i<3;i++)this.spawnZombie('bungee',Math.floor(this.random()*s.rows));}for(let i=0;i<2;i++)this.spawnZombie(i?'bucket':'cone',Math.floor(this.random()*s.rows));}}}
