// Skill mode is additive: the classic simulation never allocates skill state.
// Counters advance at successful action hooks, never on idle firing timers.
function skillDefinitions(){return typeof module!=='undefined'&&module.exports?require('./skills.js'):root.PVZSkills;}
Game.prototype.initSkill=function(p){const def=skillDefinitions().getSkill(p.kind);if(!def||!def.enabled||def.classification!=='persistent'){delete p.skill;return;}p.skill={charge:0,threshold:def.threshold,phase:'charging',remaining:0,attackMultiplier:1,rateMultiplier:1,activations:0,actionSerial:0};if(['wall-nut','tall-nut','pumpkin'].includes(p.kind))p.skill.threshold=p.maxHp/8;};
