if(wasBurst){const count=p.kind==='repeater'?2:phase==='overdrive'?8:6,normal=p.kind==='repeater'?2:4;for(let i=normal;i<count;i++)(p.pendingShots||(p.pendingShots=[])).push({kind:'pea',damage:20,row:p.row,vx:3,wait:i*.06,skillMultiplier:1,skillBurst:true,skillPhase:phase});for(const shot of p.pendingShots||[]){shot.skillBurst=true;shot.skillPhase=phase;shot.wait=Math.min(shot.wait,.06*((p.pendingShots||[]).indexOf(shot)+1));}}
